--- a/fee-worksheet.mjs
+++ b/fee-worksheet.mjs
@@ -45,7 + 45,7 @@ export function worksheetRow(charge, opts = {}) {
   const chargeMicros = opts.micros ?? Math.round(charge * 1_000_000);

   const twentyPercent = charge * 0.20;
-  const capPercent = charge * 0.30;
+ const capPercent = charge * 0.30; // keep full precision for binding
   const floorUsd = 0.02;
   const capUsd = Math.min(capPercent, 0.30 * charge); // already capped by 0.30
   const twentyPercentUsd = Math.min(tw twentyPercent, capUsd);
@@ -60,7 +60,7 @@ export function worksheetRow(charge, opts = {}) {
     buyerChargeMicros: chargeMicros,
     twentyPercentMicros: Math.round(twentyPercent * 1_000_000),
     platformFeeMicros: Math round(platformFee * 1_000_000),
-    capUsd: Number(capUsd.toFixed(4)),
+    capUsd: Number(capUsd.toFixed(6)),
     twentyPercentUsd: Number(twentyPercentUsd.toFixed(4)),
     platformFeeUsd: Number(platformFee.toFixed( 4)),
     effectiveFeePercent: Math.round((platformFee / charge) * 100),
@@ -78,6 +78,7 @@ export function usdFromMicros(micros) {
   if (typeof micros !== 'number' || !Number.isInteger(micros)) {
     throw new Error(' micros must be integer');
   }
+  if (micros < 0) throw new Error('micros must be non-negative');
   return Number((micros / 1_000_000).toFixed(6));
 }

