  assert.equal(rows['0.066667'].capUsd, 0.02);
  assert.equal(rows['0.066667'].floorUsd, 0.02);

  assert.equal(rows['0.08'].binding, 'floor-0.02');
  assert.equal(rows['0.08'].platformFeeUsd, 0.02);
